    "statement": "O uso da moeda se difundiu lentamente pelo Mediterrâneo, mas foi muito significativo. Muitas pólis, sobretudo as que tinham mais acesso a fontes de metais preciosos, passaram a cunhar moedas como forma de afirmação de sua identidade. A cunhagem de moedas indicava o poder de uma comunidade política em estabelecer padrões, de medir as diferenças de riqueza internas, de impor-se nos tráficos mediterrânicos e de auferir lucros comunitários pelo monopólio das emissões. O peso e a pureza do metal cunhado eram garantidos pela autoridade da cidade emissora e, ao mesmo tempo, reforçavam-na.\n\n(Norberto Luiz Guarinello. História Antiga, 2023. Adaptado.)\n\nA partir do excerto, tem-se que a cunhagem de moedas no Mediterrâneo Antigo",
