    "detail": "Filosofia — UEA 2025 Acompanhamento I",
    "difficulty": "Fácil",
    "statement": "Na tradição africana, a palavra falada, além de seu valor fundamental, possui um caráter sagrado que se associa à sua origem divina e às forças ocultas nela depositadas. A tradição oral, que não se limita aos contos e lendas nem aos relatos míticos e históricos, é a grande escola da vida, recobrindo e englobando todos os seus aspectos. Nela, o espiritual e o material não se dissociam. Falando segundo a compreensão de cada pessoa, ela se coloca ao alcance de todos.\n\nA tradição oral é, ao mesmo tempo, religião, conhecimento, ciência natural, aprendizado de ofício, história, divertimento e recreação. Baseada na prática e na experiência, ela se relaciona à totalidade do ser humano e, assim, contribui para criar um tipo especial de pessoa e moldar sua alma.\n\n(Nei Lopes e Luiz Antonio Simas.\n\nFilosofias africanas: uma introdução, 2022. Adaptado.)\n\nDe acordo com o excerto, na tradição africana, a linguagem verbal",
