    "statement": "Centenas de artefatos revelaram uma complexa rede comercial dos astecas, que incluía trocas com sociedades rivais para obter diferentes tipos de obsidiana. Os astecas usavam esse vidro vulcânico para fazer ferramentas, peças ornamentais ou objetos religiosos há séculos. O antropólogo Diego Matadamas-Gomora e sua equipe de pesquisa ficaram surpresos com a variedade de tipos de obsidiana encontrados na antiga capital, que supera a encontrada em outros locais da Mesoamérica. A descoberta também lança luz sobre como a sociedade asteca evoluiu antes da queda do império em 1520, ao mostrar como o uso da obsidiana mudou ao longo do tempo.\n\n(Ashley Strickland. www.cnnbrasil.com.br, 16.05.2025. Adaptado.)\n\nO uso do vidro vulcânico pelos astecas, como retratado no excerto, revela a",
