    "statement": "Os indígenas estão tendo maior acesso às universidades públicas. Em 2022, pouco mais de 6 mil indígenas estavam matriculados em uma das 26 instituições de Ensino Superior da Amazônia Legal. Esse número é três vezes maior do que em 2013, primeiro ano de aplicação da Lei Federal de Cotas (12.711/2012). Entre 2012 e 2022, o total de estudantes indígenas matriculados cresceu 245% nessa região. Por outro lado, em 10 anos, de 2012 a 2022, 53 757 indígenas se matricularam em cursos de graduação públicos na Amazônia Legal, mas apenas 5 327 concluíram os estudos, o que representa uma taxa de conclusão inferior a 10%.\n\n(Daniela Souza et al.\n\nhttps://infoamazonia.org, 14.10.2024. Adaptado.)\n\nOs dados abordados no excerto sobre a Amazônia Legal revelam que",
