    "statement": "No final do século XVIII, os químicos Antoine Lavoisier e Joseph Proust elaboraram, respectivamente, as leis da conservação da massa e das proporções definidas. No entanto, essas ideias ainda careciam de uma explicação baseada na estrutura da matéria. Foi apenas no início do século XIX que surgiu o primeiro modelo atômico capaz de justificar essas leis, marcando o início da teoria atômica moderna. Esse modelo foi proposto por",
