    "statement": "O processo de eletrização por indução é um procedimento capaz de eletrizar um corpo que inicialmente estava neutro — ou seja, o corpo induzido — por intermédio de uma sequência de ações com um corpo já eletrizado — isto é, o corpo indutor. Para que esse procedimento seja concretizado, é necessário utilizar um terceiro corpo, muito maior que os dois primeiros, capaz de receber ou ceder elétrons. Esse terceiro corpo é conhecido como aterramento. Considere que A é o corpo indutor, B é o corpo induzido e C é o aterramento. Na sequência, estão expressas quatro fases do processo de eletrização por indução, apresentadas em ordem aleatória. 1 – Afasta-se o corpo B do corpo A; 2 – Encosta-se o corpo C no corpo B; 3 – Aproxima-se o corpo B do corpo A; 4 – Separa-se o corpo C do corpo B. A ordem das fases que constituem o procedimento de eletrização por indução corresponde à sequência",
