    "statement": "Um cacto solitário, cuja figura sugere a de um ser humano, ergue-se ante uma noite de lua minguante. A lua, quadro de 1928, considerado um marco da pintura antropofágica de Tarsila do Amaral, foi comprada pelo Museu de Arte Moderna de Nova York (MoMA), por aproximadamente 20 milhões de dólares. A obra, que representa o rompimento definitivo da artista com a tradição da pintura, converteu-se na mais cara já vendida de um artista brasileiro. A lua era a favorita de um dos maiores admiradores de Tarsila: o poeta modernista Oswald de Andrade, que foi seu marido. Com ela, Tarsila construiu o casamento definitivo entre a tradição brasileira e a vanguarda artística europeia.\n\n(Joana Oliveira. “A lua, de Tarsila do Amaral, chega\n\nao MoMA e consagra brasileira no panteão modernista”.\n\nhttps://brasil.elpais.com, 27.02.2019. Adaptado.)\n\nConsiderando sua dimensão onírica, a obra A lua de Tarsila do Amaral revela a influência, sobretudo, da seguinte vanguarda artística europeia:",
