    "statement": "Percebe-se que a mulher no Brasil Colônia é vista como um instrumento apenas para procriação. Ela tinha sua sexualidade reduzida à gestação; por consequência, era colocada em confinamento caseiro e, em outros momentos, em casas de recolhimento para fugir dos “defeitos naturais de seu sexo”, como sugeriu o Bispo Azeredo Coutinho: “elas [as mulheres] nascem com uma propensão violenta de agradar, ao que logo se segue o desejo de serem vistas; os homens procuram pelas armas ou letras conduzir-se ao auge da autoridade e da glória, as mulheres procuram o mesmo pelos agrados do espírito e do corpo”.\n\n(Nicole Fernandes Alves. “Silenciadas ou silenciosas? Abuso e a submissão: Trajetória das mulheres no Brasil\n\nColonial (1500-1822)”. www.ufrgs.br, 28.10.2024. Adaptado.)\n\nNo contexto do Brasil Colônia, a declaração do Bispo Azeredo Coutinho tinha como objetivo",
