    "statement": "A Comissão de Valores Mobiliários foi criada pelo Securities Exchange Act de 1934, nos Estados Unidos. Essa legislação histórica visa proteger os investidores, impondo regulamentações que garantam a divulgação completa e justa de informações financeiras, a supervisão das práticas de mercado e a administração dos requisitos de crédito para negociação de valores mobiliários. Historicamente, houve uma necessidade crescente de intervenção federal na regulamentação de valores mobiliários devido à inadequação dos esforços estaduais, o que frequentemente permitia a persistência de práticas fraudulentas.\n\n(Jon R. Carpenter. “A Comissão de Valores Mobiliários e Câmbio é estabelecida”. www.ebsco.com, 2023. Adaptado.)\n\nA criação da comissão estadunidense mencionada no excerto está ligada",
