    "statement": "Em janeiro de 1958, com o preço do petróleo relativamente baixo e a entrada da indústria automobilística no país, Juscelino Kubitschek avaliou que o desafio de abrir novas rodovias de terra vermelha e asfalto valia a pena: mandou chamar o engenheiro agrônomo Bernardo Sayão, funcionário do Ministério da Agricultura, um tocador de obras com espírito de desbravador. Juscelino propôs a Sayão cortar os cerrados do Brasil Central, nas palavras do presidente: “arrombar a selva e unir o país de norte a sul”. A rede rodoviária Belém-Brasília interligou por estrada de rodagem os estados de Goiás, Maranhão e Pará, inseriu a Amazônia no mercado brasileiro e forneceu uma nova alternativa para atenuar desequilíbrios regionais.\n\n(Lilia M. Schwarcz e Heloisa M. Starling. Brasil: uma biografia, 2018. Adaptado.)\n\nDe acordo com o excerto, a inserção da Amazônia no mercado brasileiro foi viabilizada",
