    "statement": "Pesquisadores desenvolveram mecanismos que possibilitam aos novos sistemas de inteligência artificial (IA) explicar sua cadeia de processamento passo a passo. De fato, as mensagens geradas por esses novos sistemas podem parecer uma linha estruturada de raciocínio lógico, o que parece muito surpreendente. No entanto, essas explicações são falaciosas. Quando os grandes modelos de linguagem, usados pelas IAs, afirmam “estar pensando” sobre um problema, o que fazem é apenas gerar probabilisticamente mais texto com base em valores intermediários de processamento, não necessariamente relatando os processos computacionais usados para chegar à resposta. Quando solicitados a explicar seu raciocínio, esses modelos constroem uma narrativa plausível e, muitas vezes, sugerem que seguiram uma lógica estruturada, quando na verdade fizeram meros cálculos textuais probabilísticos.\n\n(https://g1.globo.com, 23.06.2025. Adaptado.)\n\nO trecho da notícia revela que",
