    "statement": "O conceito é exato: trabalhar sem endereço fixo, viajando pelo mundo. Há anos já falamos sobre nomadismo digital e como essa modalidade de viagem pode unir o útil ao agradável. Mas, afinal, será que dá mesmo para reunir o melhor dos dois mundos e viajar trabalhando (ou trabalhar viajando)? A que se deve isso? Muito à chamada “revolução do trabalho” da última década. E, em especial, à onda de trabalho remoto que fez o número de trabalhadores autônomos crescer desde 2020, em razão da pandemia, favorecendo essa liberdade de se trabalhar em qualquer lugar do mundo.\n\n(www.terra.com.br, 24.05.2025. Adaptado.)\n\nA condição de trabalho dos chamados “nômades digitais” estabeleceu-se diante",
