    "statement": "Nos Estados Unidos da América, 20% do Produto Interno Bruto (PIB) já se originam de produtos relacionados a doença ou vício: opioides, tabaco, apostas, ultraprocessados e dispositivos digitais. Mobilizar nas pessoas aquilo que elas não controlam é agora indispensável ao sistema. Há um pretexto: liberdade de escolha.\n\n(https://outraspalavras.net, 12.03.2025. Adaptado.)\n\nConsiderando a lógica do sistema capitalista de produção, o excerto retrata",
