    "statement": "Ter ou não ter filhos? Eis a questão. Muitos casais heterossexuais, com ou sem filhos, se fazem essa pergunta, a partir dos mais variados contextos conjugais: há aqueles que optam por seguir a vida somente a dois, por exemplo, enquanto outros, após formarem uma família numerosa, desejam não gerar mais descendentes. Seja como for, o caminho para isso passa pela escolha de um método contraceptivo. Entre diversas técnicas de controle da natalidade, disponíveis atualmente, uma das mais conhecidas é a vasectomia. Porém, cercada de mitos, muitos homens, por medo, dúvidas ou desinformação, desconsideram essa possibilidade — deixando de lado uma das melhores soluções para quem não deseja mais ter filhos.\n\n(https://g1.globo.com. Adaptado.)\n\nO método contraceptivo citado no excerto pode impedir uma gravidez porque",
